const items = $input.all();
if (!items || items.length === 0) return [];

return items.map((itemObj) => {
  const item = itemObj.json;
  const id = item.id || `file-${Date.now()}`;
  const title = item.name || item.title || 'Untitled Document';
  const sender = item.owner || item.lastModifyingUser || 'Google Drive Owner';
  const originalContent = item.description || `Uploaded file: ${title} (${item.mimeType || 'document'})`;
  const eventCreatedAt = item.modifiedTime || item.createdTime || new Date().toISOString();
  const sourceUrl = item.webViewLink || `https://drive.google.com/file/d/${id}/view`;

  return {
    json: {
      externalId: id,
      title,
      sender,
      originalContent,
      eventCreatedAt,
      sourceUrl
    }
  };
});

