parameters.jsCode:
const doc = $('Normalize Drive File').first().json;
let summary = 'Google Drive document activity.';

try {
  const input = $input.first().json;
  const text = input.text || input.candidates?.[0]?.content?.parts?.[0]?.text || '';
  if (text) {
    const cleaned = text.replace(/```json|```/g, '').trim();
    const parsed = JSON.parse(cleaned);
    summary = parsed.summary || text;
  }
} catch (e) {
  summary = doc.originalContent.slice(0, 150) + '...';
}

return [{
  json: {
    source: 'google_drive',
    activity_type: 'document',
    external_id: doc.externalId,
    title: doc.title,
    sender: doc.sender,
    summary,
    original_content: doc.originalContent,
    source_url: doc.sourceUrl,
    event_created_at: doc.eventCreatedAt,
    metadata: { file_id: doc.externalId }
  }
}];
